/**
*		insertTlcmtChgReqstd : isry.couns.taskwksprt.taskwkandatdmng.mapper.TlcmtChgReqstdMapper : 재택근무지변경신청 등록
*/
	INSERT	INTO
			AYC340	AA		/** 재택근무지 변경 **/
			(
					INDEX_SN
				,	CNSLTNT_ID
				,	HMTRC_WORK_CHG_YMD
				,	HMTRC_WORK_CS_CN
				,   ZIP
				,	TRPR_ADDR
				,	TRPR_LCTN_DADDR
				,	APRV_STTS_SE_CD			/** 승인상태 구분코드 대기 : 0 **/					
				,	DEL_YN
				,	FRST_RGTR_ID
				,	FRST_REG_DT
				,	LAST_MDFR_ID
				,	LAST_MDFCN_DT
			)
	VALUES
			(
					AYC340_SQ01.NEXTVAL
				,	#{cnsltntId}
				,	#{hmtrcWorkChgYmd}
				,	#{hmtrcWorkCsCn}
				,   #{zip}
				,	#{trprAddr}
				,	#{trprLctnDaddr}
				,	'0'					
				,	'N'
				,	#{loginId}
				,	SYSDATE
				,	#{loginId}
				,	SYSDATE
			)
